namespace InventoryTracker.Api.Domain;

/// <summary>
/// One raw material of a recipe and the amount one unit of the finished product needs (US-08). Table <c>RecipeLines</c>.
/// </summary>
public class RecipeLine
{
    /// <summary>Primary key, generated by the database.</summary>
    public int Id { get; set; }

    /// <summary>Foreign key to the recipe (the finished product's id).</summary>
    public int FinishedProductId { get; set; }

    /// <summary>The recipe, when loaded.</summary>
    public Recipe Recipe { get; set; } = null!;

    /// <summary>Position in the recipe, from 1, as submitted. Messages list materials in this order (design 7.3).</summary>
    public int LineNo { get; set; }

    /// <summary>Foreign key to the raw material. AC-08.2: a material appears at most once per recipe.</summary>
    public int RawMaterialId { get; set; }

    /// <summary>The raw material, when loaded.</summary>
    public Item RawMaterial { get; set; } = null!;

    /// <summary>AC-08.2: amount of raw material per unit of finished product; greater than 0, up to 6 decimal places.</summary>
    public decimal AmountPerUnit { get; set; }
}
